import math
import sys
import cmath

# Set recursion limit if needed, though not strictly required for this logic
sys.setrecursionlimit(2000)

eps = 1e-6
PI = math.acos(-1.0)
EPS = eps
pi = PI

class Point:
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def __repr__(self):
        # Mimic the C++ operator<< behavior: (x,y) with 0 if close to 0
        x_str = "0" if abs(self.x) < eps else str(self.x)
        y_str = "0" if abs(self.y) < eps else str(self.y)
        return f"({x_str},{y_str})"

    def set(self, x, y):
        self.x = x
        self.y = y

    def read(self):
        # Not used in main logic as we parse input manually, but kept for structure
        pass

    def print(self, end=""):
        # Not used in main logic
        pass

    def rot90(self):
        return Point(-self.y, self.x)

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def __mul__(self, val):
        return Point(self.x * val, self.y * val)

    def __truediv__(self, val):
        return self * (1.0 / val)

# Typedef
Vec = Point

def PtoV(a, b):
    # Vector from a to b
    return Vec(b.x - a.x, b.y - a.y)

def dMult(a, b):
    # Dot product
    return (a.x * b.x) + (a.y * b.y)

def xMult(a, b):
    # Cross product (2D scalar)
    return a.x * b.y - a.y * b.x

def VecMod(a):
    # Magnitude
    return math.sqrt(dMult(a, a))

def VecMod2(a):
    # Magnitude squared
    return dMult(a, a)

def Corner2V(a, b):
    # Angle between two vectors in radians
    dot = dMult(a, b)
    mod_a = VecMod(a)
    mod_b = VecMod(b)
    if mod_a == 0 or mod_b == 0:
        return 0.0
    cos_val = dot / (mod_a * mod_b)
    # Clamp to [-1, 1] to avoid domain errors in acos due to floating point precision
    if cos_val > 1.0:
        cos_val = 1.0
    elif cos_val < -1.0:
        cos_val = -1.0
    return abs(math.acos(cos_val))

def VecUnit(a):
    # Unit vector
    mod = VecMod(a)
    if mod == 0:
        return Vec(0, 0)
    return a / mod

def VRotate(v, alph):
    # Rotate vector v by alph radians counter-clockwise
    sa = math.sin(alph)
    ca = math.cos(alph)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)

def PRotate(p, o, alph):
    # Rotate point p around origin o by alph radians
    return o + VRotate(PtoV(o, p), alph)

def GetVV(v):
    # Perpendicular vector
    return VRotate(v, pi / 2)

def ShadowPOnLine(p, a, b):
    # Projection of point p onto line ab
    ab = PtoV(a, b)
    ap = PtoV(a, p)
    # Projection vector = (ab . ap) / |ab|^2 * ab
    # C++ code: VecUnit(ab) * dMult(ab,ap) / VecMod(ab)
    # This is equivalent to (ab / |ab|) * (ab . ap) / |ab| = ab * (ab . ap) / |ab|^2
    mod_ab = VecMod(ab)
    if mod_ab < eps:
        return a
    alpha = VecUnit(ab) * (dMult(ab, ap) / mod_ab)
    return a + alpha

def LineCrossCircle(a, b, o, r):
    # Intersection points of line ab and circle centered at o with radius r
    ret = []
    t = ShadowPOnLine(o, a, b)
    ot = PtoV(o, t)
    dist_ot = VecMod(ot)

    if dist_ot - r > eps:
        return ret

    if abs(dist_ot - r) < eps:
        ret.append(t)
        return ret

    lr = math.sqrt(r * r - VecMod2(ot))
    # Direction from t to a and t to b
    ta_dir = VecUnit(PtoV(t, a))
    tb_dir = VecUnit(PtoV(t, b))

    ta = t + ta_dir * lr
    tb = t + tb_dir * lr

    ret.append(ta)
    ret.append(tb)
    return ret

def PointTangentCircle(p, o, r):
    # Tangent points from point p to circle centered at o with radius r
    x2 = VecMod2(p - o)
    d2 = x2 - r * r
    ret = []

    if d2 < -eps:
        return ret

    if r <= eps:
        ret.append(o)
        ret.append(o)
        return ret

    d2 = max(d2, 0.0)

    q1 = o + (p - o) * (r * r / x2)
    q2 = (p - o).rot90() * (-r * math.sqrt(d2) / x2)

    ret.append(q1 - q2)
    ret.append(q1 + q2)
    return ret

def POnSeg(p, a, b):
    # Check if point p lies on segment ab
    if abs(xMult(PtoV(a, b), PtoV(a, p))) > eps:
        return False
    if min(a.x, b.x) > p.x or p.x > max(a.x, b.x):
        return False
    if min(a.y, b.y) > p.y or p.y > max(a.y, b.y):
        return False
    return True

def PDisLine(p, a, b):
    # Distance from point p to line ab
    shadow = ShadowPOnLine(p, a, b)
    return VecMod(shadow - p)

# Global variables for the check function
p_global = Point()
s_global = Point()
vp = 0.0
vs = 0.0
r_global = 0.0
sita = 0.0

def check(t):
    len_or = VecMod(p_global)
    if len_or < eps:
        # If p is at origin, angle is undefined, but cos/sin might handle it or we need special case
        # In C++, acos(p.x/VecMod(p)) would be acos(0/0) which is undefined. 
        # However, if p is origin, the motion is undefined or zero. 
        # Assuming p is not origin in valid inputs.
        angle = sita + t * vp / len_or if len_or > 0 else 0
    else:
        angle = sita + t * vp / len_or

    e = Point(len_or * math.cos(angle), len_or * math.sin(angle))

    ccp = LineCrossCircle(s_global, e, Point(0, 0), r_global)

    if len(ccp) != 2 or (not POnSeg(ccp[0], s_global, e) and not POnSeg(ccp[1], s_global, e)):
        # If no intersection on the segment, path is straight line
        return vs * t > VecMod(e - s_global)

    ttp1 = PointTangentCircle(s_global, Point(0, 0), r_global)
    if len(ttp1) < 2:
        # Fallback if tangents not found (should not happen if outside)
        return vs * t > VecMod(e - s_global)

    # Sort ttp1 based on distance to line se
    if PDisLine(ttp1[0], s_global, e) > PDisLine(ttp1[1], s_global, e):
        ttp1[0], ttp1[1] = ttp1[1], ttp1[0]

    l1 = VecMod(PtoV(s_global, ttp1[0]))

    ttp2 = PointTangentCircle(e, Point(0, 0), r_global)
    if len(ttp2) < 2:
        return vs * t > VecMod(e - s_global)

    if PDisLine(ttp2[0], s_global, e) > PDisLine(ttp2[1], s_global, e):
        ttp2[0], ttp2[1] = ttp2[1], ttp2[0]

    l2 = VecMod(PtoV(e, ttp2[0]))

    alph = Corner2V(PtoV(Point(0, 0), ttp1[0]), PtoV(Point(0, 0), ttp2[0]))

    total_dist = VecMod(PtoV(s_global, ttp1[0])) + VecMod(PtoV(e, ttp2[0])) + alph * r_global

    return total_dist < vs * t

def main():
    input_stream = sys.stdin
    output_stream = sys.stdout

    for line in input_stream:
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) < 7:
            continue

        try:
            p_x = float(parts[0])
            p_y = float(parts[1])
            vp_val = float(parts[2])
            s_x = float(parts[3])
            s_y = float(parts[4])
            vs_val = float(parts[5])
            r_val = float(parts[6])
        except ValueError:
            continue

        global p_global, s_global, vp, vs, r_global, sita

        p_global = Point(p_x, p_y)
        s_global = Point(s_x, s_y)
        vp = vp_val
        vs = vs_val
        r_global = r_val

        mod_p = VecMod(p_global)
        if mod_p < eps:
            sita = 0.0
        else:
            sita = math.acos(p_global.x / mod_p)
            if p_global.y < 0:
                sita = -sita

        left = 0.0
        right = 1e10

        # Binary search for the time
        # C++ uses while(fabs(left-right) > 1e-12)
        while abs(left - right) > 1e-12:
            mid = (left + right) * 0.5
            if check(mid):
                right = mid
            else:
                left = mid

        # Output with 9 decimal places
        output_stream.write(f"{left:.9f}\n")

if __name__ == "__main__":
    main()

