import math
import sys
from math import sqrt, sin, cos, acos, fabs, pi

eps = 1e-6
N = 100 + 10

class Point:
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def set(self, x, y):
        self.x = x
        self.y = y

    def read(self):
        # In Python, we usually handle input differently, but keeping structure
        pass

    def print(self, end=""):
        print(f"{self.x:.6f} {self.y:.6f}{end}", end="")

    def rot90(self):
        return Point(-self.y, self.x)

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def __mul__(self, val):
        return Point(self.x * val, self.y * val)

    def __truediv__(self, val):
        return self * (1.0 / val)

    def __repr__(self):
        # Mimicking the C++ operator<< behavior roughly
        x_str = "0" if fabs(self.x) < eps else str(self.x)
        y_str = "0" if fabs(self.y) < eps else str(self.y)
        return f"({x_str},{y_str})"

Vec = Point

def PtoV(a, b):
    return Vec(b.x - a.x, b.y - a.y)

def dMult(a, b):
    return (a.x * b.x) + (a.y * b.y)

def xMult(a, b):
    return a.x * b.y - a.y * b.x

def VecMod(a):
    return sqrt(dMult(a, a))

def VecMod2(a):
    return dMult(a, a)

def Corner2V(a, b):
    return fabs(acos(dMult(a, b) / VecMod(a) / VecMod(b)))

def VecUnit(a):
    return a / VecMod(a)

def VRotate(v, alph):
    sa = sin(alph)
    ca = cos(alph)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)

def PRotate(p, o, alph):
    return o + VRotate(PtoV(o, p), alph)

def GetVV(v):
    return VRotate(v, pi / 2)

def ShadowPOnLine(p, a, b):
    ab = PtoV(a, b)
    ap = PtoV(a, p)
    alph = VecUnit(ab) * dMult(ab, ap) / VecMod(ab)
    return a + alph

def LineCrossCircle(a, b, o, r):
    ret = []
    t = ShadowPOnLine(o, a, b)
    ot = PtoV(o, t)
    if VecMod(ot) - r > eps:
        return ret
    if fabs(VecMod(ot) - r) < eps:
        ret.append(t)
        return ret
    lr = sqrt(r * r - VecMod2(ot))
    ta = t + VecUnit(PtoV(t, a)) * lr
    tb = t + VecUnit(PtoV(t, b)) * lr
    ret.append(ta)
    ret.append(tb)
    return ret

def PointTangentCircle(p, o, r):
    x2 = VecMod2(p - o)
    d2 = x2 - r * r
    ret = []
    if d2 < -eps:
        return ret
    if r <= eps:
        ret.append(o)
        ret.append(o)
        return ret
    d2 = max(d2, 0.0)
    q1 = o + (p - o) * (r * r / x2)
    q2 = (p - o).rot90() * (-r * sqrt(d2) / x2)
    ret.append(q1 - q2)
    ret.append(q1 + q2)
    return ret

def POnSeg(p, a, b):
    if fabs(xMult(PtoV(a, b), PtoV(a, p))) > eps:
        return False
    if min(a.x, b.x) > p.x or p.x > max(a.x, b.x):
        return False
    if min(a.y, b.y) > p.y or p.y > max(a.y, b.y):
        return False
    return True

def PDisLine(p, a, b):
    return VecMod(ShadowPOnLine(p, a, b) - p)

def debug_function():
    h = Point(25, 45)
    j = Point(30, 30)
    i = Point(15, 35)
    k = Point(5, 45)
    aaa = Point(0, 0)
    bbb = Point(0, 5)
    ppp = Point(0, -1)
