    print(f"π: {pi}\t\tπ checked")
    print(f"{i}{h}{j}\tio checked")
    print(f"{Corner2V(PtoV(i, h), PtoV(i, j)) * (180 / pi)}\t\t\tCorner2V() checked")
    i.set(0, 0)
    k.set(-10, 4)
    print(f"{VRotate(PtoV(i, k), pi / 2)} {PtoV(i, k)}{PtoV(i, Point(-4, -10))}VRotate() checked")
    p = Point(10, 2)
    a = Point(-6, 6)
    b = Point(10, -10)
    print(f"{ShadowPOnLine(p, a, b)}\t\t\tShadowPOnLine() checked")
    r = 6.64
    CP = LineCrossCircle(a, b, Point(0, 0), r)
    print(f"cross point: {len(CP)} ", end="")
    for pt in CP:
        print(pt, end=" ")
    print("\tchecked")
    p.set(10, 2)
