p_global = None
s_global = None
vp_global = 0.0
vs_global = 0.0
r_global = 0.0
sita_global = 0.0

def check(t):
    global p_global, s_global, vp_global, vs_global, r_global, sita_global
    len_or = VecMod(p_global)
    e = Point(len_or * cos(sita_global + t * vp_global / len_or),
              len_or * sin(sita_global + t * vp_global / len_or))
    ccp = LineCrossCircle(s_global, e, Point(0, 0), r_global)
    if len(ccp) != 2 or (not POnSeg(ccp[0], s_global, e) and not POnSeg(ccp[1], s_global, e)):
        return vs_global * t > VecMod(e - s_global)
    ttp1 = PointTangentCircle(s_global, Point(0, 0), r_global)
    if PDisLine(ttp1[0], s_global, e) > PDisLine(ttp1[1], s_global, e):
        ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
    l1 = VecMod(PtoV(s_global, ttp1[0]))
    ttp2 = PointTangentCircle(e, Point(0, 0), r_global)
    if PDisLine(ttp2[0], s_global, e) > PDisLine(ttp2[1], s_global, e):
