    # Clamp value to [-1, 1] to avoid domain errors in acos due to floating point precision
    dot = dMult(a, b)
    mod_a = VecMod(a)
    mod_b = VecMod(b)
    if mod_a == 0 or mod_b == 0:
        return 0.0
    cos_val = dot / (mod_a * mod_b)
    cos_val = max(-1.0, min(1.0, cos_val))
    return abs(math.acos(cos_val))

